import React, { useEffect, useMemo, useState } from "react";
import DashboardLayout from "../components/DashboardLayout";
import SearchBar from "../components/SearchBar";
import Table from "../components/Table";
import api from "../services/api";

const TeacherDashboard = () => {
  const [students, setStudents] = useState([]);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    const fetchStudents = async () => {
      const response = await api.get(`/teacher/students?search=${encodeURIComponent(debouncedSearch)}`);
      setStudents(response.data.students);
    };
    fetchStudents();
  }, [debouncedSearch]);

  const studentsBySection = useMemo(() => {
    return students.reduce((acc, student) => {
      const key = `${student.class_grade}-${student.division}`;
      if (!acc[key]) {
        acc[key] = [];
      }
      acc[key].push(student);
      return acc;
    }, {});
  }, [students]);

  return (
    <DashboardLayout title="Teacher Dashboard">
      <div className="panel">
        <SearchBar value={search} onChange={setSearch} placeholder="Search..." />
      </div>
      {Object.keys(studentsBySection)
        .sort()
        .map((sectionKey) => {
          const rows = studentsBySection[sectionKey].map((student) => [
            student.name,
            student.roll_number,
            sectionKey,
            student.parent_email,
          ]);

          return (
            <div className="panel" key={sectionKey}>
              <h3>Class Section {sectionKey}</h3>
              <Table headers={["Name", "Roll", "Class", "Parent Email"]} rows={rows} />
            </div>
          );
        })}
    </DashboardLayout>
  );
};

export default TeacherDashboard;
